fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>> {
    // Number of rows in the input matrix
    let rows = arr.len();
    // Number of columns in the input matrix (assume arr is non‐empty)
    let cols = arr[0].len();

    // Prepare the output matrix with `cols` rows, each with capacity for `rows` elements
    let mut result: Vec<Vec<i8>> = Vec::with_capacity(cols);
    for _ in 0..cols {
        result.push(Vec::with_capacity(rows));
    }

    // Fill in the transposed entries: result[j][i] = arr[i][j]
    for i in 0..rows {
        for j in 0..cols {
            result[j].push(arr[i][j]);
        }
    }

    result
}

